/* ---------- 我方气泡：浅蓝方圆（#bde1fb）缩小版 + 右侧中间装饰 + 左侧外侧装饰 ---------- */
:root {
  /* 我方气泡颜色 */
  --bubble-me-bg: #bde1fb;
  --bubble-me-color: #1a1a1a;

  /* 我方气泡圆角（缩小版：保持方圆感） */
  --bubble-me-radius: 10px;
  --bubble-me-radius-first: 10px 10px 5px 10px;
  --bubble-me-radius-mid: 10px 5px 5px 10px;
  --bubble-me-radius-last: 10px 5px 10px 10px;

  /* 缩小内边距（右侧留出空间给装饰图） */
  --bubble-me-padding: 6px 6px 6px 10px;

  /* 缩小字号 */
  --bubble-me-font-size: 13px;

  /* 轻微阴影 */
  --bubble-me-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);

  /* 我方气泡内链接颜色 */
  --bubble-me-link-color: #0066cc;
}
/* ---------- 对方气泡：白色方圆（无边框）缩小版 + 左侧中间装饰 ---------- */
:root {
  /* 对方气泡颜色 */
  --bubble-them-bg: #ffffff;
  --bubble-them-color: #1f2d3d;

  /* 对方气泡圆角（缩小版） */
  --bubble-them-radius: 10px;
  --bubble-them-radius-first: 10px 10px 10px 5px;
  --bubble-them-radius-mid: 5px 10px 10px 5px;
  --bubble-them-radius-last: 5px 10px 10px 10px;

  /* 缩小内边距（左侧留出空间给装饰图） */
  --bubble-them-padding: 6px 10px 6px 6px;

  /* 缩小字号 */
  --bubble-them-font-size: 13px;

  /* 无边框 */
  --bubble-them-border: none;

  /* 轻微阴影 */
  --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);

  /* 对方气泡内链接颜色 */
  --bubble-them-link-color: #0066cc;
}
/* ---------- 头像与气泡间距调整 ---------- */
/* 对方头像（左侧）与气泡的间距 */
.msg-them .msg-avatar-them-container {
  margin-right: 5px !important;
}
/* 我方头像（右侧）与气泡的间距 */
.msg-me .msg-avatar-me-container {
  margin-left: 5px !important;
}
/* 消息外层容器间距控制 */
.msg-them {
  gap: 5px !important;
}
.msg-me {
  gap: 5px !important;
}
/* ---------- 气泡通用增强 ---------- */
.bubble-me-custom,
.bubble-them-custom {
  position: relative !important;
  overflow: visible !important;
  border-radius: var(--bubble-radius, 10px) !important;
  padding: var(--bubble-me-padding, 6px 10px) !important;
  font-size: var(--bubble-me-font-size, 13px) !important;
  line-height: 1.4 !important;
}
.bubble-them-custom {
  padding: var(--bubble-them-padding, 6px 10px) !important;
  font-size: var(--bubble-them-font-size, 13px) !important;
}
/* ========== 我方气泡装饰1：右侧中间 ========== */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  right: -10px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 14px !important;
  height: 14px !important;
  background: url("https://img.cdn1.vip/i/69cf3faad2200_1775189930.png") no-repeat center/contain !important;
  pointer-events: none !important;
  z-index: 10 !important;
}
/* ========== 我方气泡装饰2：左侧外侧 ========== */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  left: -18px !important;
  top: 65% !important;
  transform: translateY(-50%) !important;
  width: 14px !important;
  height: 14px !important;
  background: url("https://image.uglycat.cc/x2kfea.png") no-repeat center/contain !important;
  pointer-events: none !important;
  z-index: 10 !important;
}
/* ========== 对方气泡装饰：左侧中间 ========== */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  left: -9px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: 12px !important;
  height: 12px !important;
  background: url("https://img.cdn1.vip/i/69cf32f5e4381_1775186677.png") no-repeat center/contain !important;
  pointer-events: none !important;
  z-index: 10 !important;
}
/* ---------- 单独/首条/中间/末条圆角精细化覆盖 ---------- */
.bubble-me-custom.first {
  border-radius: var(--bubble-me-radius-first, 10px 10px 5px 10px) !important;
}
.bubble-me-custom.mid {
  border-radius: var(--bubble-me-radius-mid, 10px 5px 5px 10px) !important;
}
.bubble-me-custom.last {
  border-radius: var(--bubble-me-radius-last, 10px 5px 10px 10px) !important;
}
.bubble-me-custom.single {
  border-radius: var(--bubble-me-radius, 10px) !important;
}
.bubble-them-custom.first {
  border-radius: var(--bubble-them-radius-first, 10px 10px 10px 5px) !important;
}
.bubble-them-custom.mid {
  border-radius: var(--bubble-them-radius-mid, 5px 10px 10px 5px) !important;
}
.bubble-them-custom.last {
  border-radius: var(--bubble-them-radius-last, 5px 10px 10px 10px) !important;
}
.bubble-them-custom.single {
  border-radius: var(--bubble-them-radius, 10px) !important;
}
/* 确保装饰容器也允许溢出（防止装饰被裁剪） */
.bubble-deco-me,
.bubble-deco-them {
  overflow: visible !important;
}
/* ---------- 消息间距优化 ---------- */
.chat-messages-area {
  --chat-messages-gap: 2px;
}
.msg-bubble-container {
  margin-bottom: 1px !important;
}
:root {
  --chat-message-max-width: 75%;
}
/* 双方气泡均为纯色方圆气泡，无边框，带装饰贴图 */
/* =========================================
   特殊消息（图片/视频/卡片等）自动隐藏装饰
========================================= */
/* 当气泡内包含图片、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒时，隐藏所有装饰 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after {
  display: none !important;
}
/* ================================================
 * 消息间距微调
 * ================================================ */
.chat-message-list-custom .msg-bubble-container {
  margin-bottom: 1px !important;
}
.bubble-me-custom.first,
.bubble-them-custom.first {
  margin-top: 5px;
}
/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* ========== 底栏语音按钮：隐藏视觉但保留点击 ========== */
.input-btn-mic {
  display: flex !important;        /* 覆盖之前的 display:none，保留占位和点击 */
  opacity: 0 !important;           /* 完全透明不可见 */
  width: 36px !important;          /* 保持原有宽度 */
  height: 36px !important;         /* 保持原有高度 */
  min-width: 36px !important;      /* 防止被压缩 */
  pointer-events: auto !important; /* 确保可以点击 */
  cursor: pointer !important;      /* 鼠标指针样式 */
}
/* 同时隐藏语音按钮内的任何 SVG 图标 */
.input-btn-mic svg {
  display: none !important;
}

